package com.auth.crypto

import kotlinx.coroutines.*
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.Mac
import javax.crypto.spec.IvParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import kotlin.system.measureNanoTime

data class TokenValidationResult(
    val valid: Boolean,
    val userId: String? = null,
    val errorCode: Int = 0
)

class AuthTokenService(
    private val keyBytes: ByteArray,
    private val macKeyBytes: ByteArray = keyBytes,
    private val rateLimiter: RateLimiter = RateLimiter()
) {
    private val key = SecretKeySpec(keyBytes, "AES")
    private val macKey = SecretKeySpec(macKeyBytes, "HmacSHA256")
    private val tokenCache = ConcurrentHashMap<String, TokenValidationResult>()

    suspend fun validateToken(encryptedToken: String): TokenValidationResult {
        tokenCache[encryptedToken]?.let { return it }

        if (!rateLimiter.allowRequest(encryptedToken)) {
            return TokenValidationResult(false, errorCode = 429)
        }

        val result = withContext(Dispatchers.Default) {
            performValidation(encryptedToken)
        }

        if (result.valid) {
            tokenCache[encryptedToken] = result
        }
        return result
    }

    private fun performValidation(encryptedToken: String): TokenValidationResult {
        val rawBytes = try {
            Base64.getDecoder().decode(encryptedToken)
        } catch (e: IllegalArgumentException) {
            return TokenValidationResult(false, errorCode = 400)
        }

        if (rawBytes.size < 32) {
            return TokenValidationResult(false, errorCode = 400)
        }

        val iv = rawBytes.sliceArray(0 until 16)
        val ciphertext = rawBytes.sliceArray(16 until rawBytes.size)

        val plaintext = try {
            decryptCBC(ciphertext, iv)
        } catch (e: Exception) {
            return TokenValidationResult(false, errorCode = 401)
        }

        return validateDecryptedPayload(plaintext)
    }

    private fun validateDecryptedPayload(plaintext: ByteArray): TokenValidationResult {
        val paddingValid = checkPKCS7Padding(plaintext)
        val unpaddedPayload = if (paddingValid) {
            val paddingLen = plaintext.last().toInt() and 0xFF
            plaintext.sliceArray(0 until plaintext.size - paddingLen)
        } else {
            plaintext
        }

        val payloadResult = parseAndValidatePayload(unpaddedPayload)

        // Both padding AND payload must be valid — single error code for both
        return if (paddingValid && payloadResult.valid) {
            payloadResult
        } else {
            TokenValidationResult(false, errorCode = 401)
        }
    }

    private fun decryptCBC(ciphertext: ByteArray, iv: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/CBC/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key, IvParameterSpec(iv))
        return cipher.doFinal(ciphertext)
    }

    internal fun checkPKCS7Padding(data: ByteArray): Boolean {
        if (data.isEmpty()) return false

        val paddingLen = data.last().toInt() and 0xFF
        if (paddingLen == 0 || paddingLen > 16) return false
        if (paddingLen > data.size) return false

        // Constant-time comparison of padding bytes
        var result = 0
        for (i in data.size - paddingLen until data.size) {
            result = result or ((data[i].toInt() and 0xFF) xor paddingLen)
        }
        return result == 0
    }

    private fun computeSignature(message: ByteArray): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(macKey)
        return mac.doFinal(message)
    }

    private fun constantTimeEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    private fun parseAndValidatePayload(payload: ByteArray): TokenValidationResult {
        val payloadStr = String(payload, Charsets.UTF_8)
        val parts = payloadStr.split(":")
        if (parts.size != 3) {
            return TokenValidationResult(false, errorCode = 401)
        }

        val (userId, timestamp, signature) = parts
        val expiry = timestamp.toLongOrNull() ?: return TokenValidationResult(false, errorCode = 401)

        // Verify the token signature (HMAC) before trusting any claim.
        val expectedSig = computeSignature("$userId:$timestamp".toByteArray(Charsets.UTF_8))
        val providedSig = try {
            Base64.getDecoder().decode(signature)
        } catch (e: IllegalArgumentException) {
            return TokenValidationResult(false, errorCode = 401)
        }
        if (!constantTimeEquals(expectedSig, providedSig)) {
            return TokenValidationResult(false, errorCode = 401)
        }

        if (System.currentTimeMillis() > expiry) {
            return TokenValidationResult(false, errorCode = 401)
        }

        return TokenValidationResult(true, userId = userId)
    }
}

class RateLimiter(
    private val maxRequests: Int = 100,
    private val windowMs: Long = 60_000
) {
    private data class RequestWindow(val count: Int, val windowStart: Long)
    private val requests = ConcurrentHashMap<String, RequestWindow>()

    fun allowRequest(clientId: String): Boolean {
        val now = System.currentTimeMillis()
        val window = requests.compute(clientId) { _, existing ->
            if (existing == null || now - existing.windowStart > windowMs) {
                RequestWindow(1, now)
            } else {
                RequestWindow(existing.count + 1, existing.windowStart)
            }
        }
        return (window?.count ?: 0) <= maxRequests
    }
}

suspend fun main() {
    val key = ByteArray(16).also { SecureRandom().nextBytes(it) }
    val macKey = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val service = AuthTokenService(key, macKey)

    coroutineScope {
        val results = (1..10).map { i ->
            async {
                val fakeToken = Base64.getEncoder().encodeToString(ByteArray(48))
                service.validateToken(fakeToken)
            }
        }
        results.awaitAll().forEach { println(it) }
    }
}
